{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "In humans, [123/124/131I]AM281—a close CB1 analog sharing the pyrazole-dichlorophenyl-hydrazide core—readily permeates the BBB and enables CB1 quantification in brain; this directly supports meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Ex vivo autoradiography in rats after IV [123I]AM281 shows good brain accumulation in CB1-rich regions, confirming that this scaffold achieves brain exposure in vivo.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "GNE-0723, a brain-penetrant heteroaryl compound, showed excellent brain penetration with no active efflux in mice, supporting that related lipophilic heteroaryl chemotypes can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A brain-penetrant PDE2A inhibitor with a heteroaryl core gave a rat CSF/Cbu ratio of 0.87, indicating robust CNS exposure for similar drug-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A BBB-permeable acylhydrazone-type compound showed increased brain penetration and was considered a beneficial CNS hit, supporting CNS access for hydrazide-containing analogs.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close structural analog of AM281, a CB1 radioligand with demonstrated human BBB permeation and rat brain autoradiographic uptake; high-transfer evidence from related brain-penetrant compounds consistently supports meaningful CNS access. No high-transfer contradictory evidence was identified.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma or CSF measurement for the exact query.",
    "Efflux-transporter status not directly measured for the query.",
    "Human data are for the iodo analog AM281 rather than the thiophene-alkyne analog."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

